from pathlib import Path


def patch_models() -> None:
    path = Path("healthia_one/education_video_models.py")
    text = path.read_text(encoding="utf-8")
    old_clean = '''def _clean_topic(raw: str) -> str:\n    text = str(raw or "").strip(" \\t\\n\\r.,;:!?")\n    text = re.sub(\n        r"(?i)\\b(?:por favor|please|por favor|s'il vous plait|bitte|per favore|un video|a video|en video|in a video|em video|explicando|que explique|sobre|acerca de|about|para entender|to explain)\\b",\n        " ", text,\n    )\n    text = re.sub(\n        r"(?i)\\b(?:crea|creame|hazme|genera|preparame|quiero|necesito|create|make|generate|prepare|i want|i need|explicame|explain|crie|quero|explique|cree|genere|erstelle|spiega|voglio)\\b",\n        " ", text,\n    )\n    text = re.sub(r"(?:ビデオ|動画|비디오|영상|видео|فيديو|वीडियो|视频|影片)", " ", text)\n    return re.sub(r"\\s+", " ", text).strip(" -")[:180]\n\n\ndef topic_from_text(value: str) -> str:\n    text = str(value or "").strip()\n    patterns = (\n        r"(?i)\\b(?:sobre|acerca de|about|sobre|sur|uber|über)\\s+(.+)$",\n        r"(?i)\\b(?:mi|my|meu|minha|mon|ma|mein|meine|mio|mia)\\s+([^,.!?]{3,140})$",\n        r"(?i)\\b(?:explicame|explícame|explain|explique|spiega)\\s+(.+?)(?:\\s+en video|\\s+in a video|\\s+em video|$)",\n    )\n    for pattern in patterns:\n        match = re.search(pattern, text)\n        if match:\n            topic = _clean_topic(match.group(1))\n            if topic and normalize(topic) not in GENERIC_REFERENCE:\n                return topic\n    topic = _clean_topic(text)\n    return "" if normalize(topic) in GENERIC_REFERENCE else topic\n'''
    new_clean = '''def _clean_topic(raw: str) -> str:\n    text = str(raw or "").strip(" \\t\\n\\r.,;:!?")\n    # Duration and style describe the requested media, never the clinical topic.\n    text = re.sub(\n        r"(?i)\\b(?:de|for|durante|por)?\\s*(?:un|una|one|um|uma)?\\s*\\d+(?:[.,]\\d+)?\\s*(?:min|minuto|minutos|minute|minutes|minuten|minuti|分钟|분|分)\\b",\n        " ", text,\n    )\n    text = re.sub(\n        r"(?i)\\b(?:corto|corta|rapido|rápido|short|quick|curto|curta|rapide|court|kurz|breve)\\b",\n        " ", text,\n    )\n    text = re.sub(\n        r"(?i)\\b(?:por favor|please|s'il vous plait|bitte|per favore|un video|a video|en video|in a video|em video|explicando|explicándome|que explique|sobre|acerca de|about|para entender|to explain)\\b",\n        " ", text,\n    )\n    text = re.sub(\n        r"(?i)\\b(?:crea|creame|créame|hazme|genera|preparame|prepárame|quiero|necesito|create|make|generate|prepare|i want|i need|explicame|explícame|explain|crie|quero|explique|cree|genere|erstelle|spiega|voglio)\\b",\n        " ", text,\n    )\n    text = re.sub(r"(?:ビデオ|動画|비디오|영상|видео|فيديو|वीडियो|视频|影片)", " ", text)\n    text = re.sub(r"(?i)^(?:que|qué|what|o que|que|was|cosa)\\s+(?:significa|means?|signifie|bedeutet)\\s+", "", text)\n    return re.sub(r"\\s+", " ", text).strip(" -")[:180]\n\n\ndef topic_from_text(value: str) -> str:\n    text = str(value or "").strip()\n    # Prefer the semantic explanation clause over modifiers such as \"short\"\n    # or \"one minute\". This is deliberately deterministic because the\n    # extracted topic controls which patient evidence HealthIA is allowed to use.\n    semantic_patterns = (\n        r"(?i)\\b(?:explicandome|explicándome|explicame|explícame)\\s+(?:que|qué)\\s+significa\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:que|qué)\\s+significa\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:explain(?:ing)?(?:\\s+to\\s+me)?|tell\\s+me)\\s+(?:what\\s+)?(?:does|is)?\\s*([^.!?]{3,180}?)(?:\\s+mean)?(?:[.!?]|$)",\n        r"(?i)\\b(?:o que significa|explique(?:-me)?(?:\\s+o que significa)?)\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:que signifie|expliquez?-moi)\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:was bedeutet|erkl[aä]r(?:e|en)?(?:\\s+mir)?)\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:cosa significa|spiegami)\\s+([^.!?]{3,180})",\n    )\n    for pattern in semantic_patterns:\n        match = re.search(pattern, text)\n        if match:\n            topic = _clean_topic(match.group(1))\n            if topic and normalize(topic) not in GENERIC_REFERENCE:\n                return topic\n\n    patterns = (\n        r"(?i)\\b(?:sobre|acerca de|about|sur|uber|über)\\s+([^.!?]{3,180})",\n        r"(?i)\\b(?:mi|my|meu|minha|mon|ma|mein|meine|mio|mia)\\s+([^,.!?]{3,140})$",\n        r"(?i)\\b(?:explicame|explícame|explain|explique|spiega)\\s+(.+?)(?:\\s+en video|\\s+in a video|\\s+em video|$)",\n    )\n    for pattern in patterns:\n        match = re.search(pattern, text)\n        if match:\n            topic = _clean_topic(match.group(1))\n            if topic and normalize(topic) not in GENERIC_REFERENCE:\n                return topic\n    # Last resort: first sentence only so follow-up intent such as \"I want to\n    # understand it simply\" cannot become part of the evidence-selection topic.\n    first_sentence = re.split(r"[.!?]+", text, maxsplit=1)[0]\n    topic = _clean_topic(first_sentence)\n    return "" if normalize(topic) in GENERIC_REFERENCE else topic\n'''
    if text.count(old_clean) != 1:
        raise RuntimeError("education topic parser contract changed")
    path.write_text(text.replace(old_clean, new_clean), encoding="utf-8")


def patch_planner() -> None:
    path = Path("healthia_one/education_video.py")
    text = path.read_text(encoding="utf-8")
    old = '''- Veo prompts must be generic medical education imagery: no names, ages, locations, dates, medication names, laboratory values, measurements, identifiers, text overlays, or PHI.\n- The veo_prompt itself must be written in English for predictable visual generation, even though every patient-visible field is in {language}.\n- Prefer controlled cards for exact values, medication names, numbers, warning signs, and clinical labels.\n- Use at most ONE scene with visual_kind="veo"; all other scenes are controlled cards.\n- Do not use a talking doctor avatar or person generation.\n'''
    new = '''- Veo prompts must be generic medical education imagery: no names, ages, locations, dates, medication names, laboratory values, measurements, identifiers, text overlays, or PHI.\n- The veo_prompt itself must be written in English for predictable visual generation, even though every patient-visible field is in {language}.\n- NEVER use digits or numeric tokens in veo_prompt, including labels such as 3D; spell generic visual concepts with words instead.\n- Prefer controlled cards for exact values, medication names, numbers, warning signs, and clinical labels.\n- Use at most ONE scene with visual_kind="veo"; all other scenes are controlled cards. For a physiological topic where motion materially improves understanding (for example blood flow, breathing, digestion, joint motion, or cardiac function), use exactly ONE generic Veo scene.\n- Do not use a talking doctor avatar or person generation.\n'''
    if text.count(old) != 1:
        raise RuntimeError("education planner instruction contract changed")
    path.write_text(text.replace(old, new), encoding="utf-8")


def patch_tests() -> None:
    path = Path("tests/test_education_video_core.py")
    text = path.read_text(encoding="utf-8")
    addition = '''\n\ndef test_direct_spanish_video_request_extracts_clinical_topic_not_duration():\n    from healthia_one.education_video_models import requested_duration_seconds, topic_from_text\n\n    request = (\n        "Crea un video corto de un minuto explicándome qué significa la hipertensión "\n        "y mi presión arterial. Quiero entenderlo de forma sencilla."\n    )\n    topic = topic_from_text(request)\n    assert "hipertensión" in topic.lower() or "hipertension" in topic.lower()\n    assert "presión arterial" in topic.lower() or "presion arterial" in topic.lower()\n    assert "un minuto" not in topic.lower()\n    assert "corto" not in topic.lower()\n    assert requested_duration_seconds(request) == 60\n\n\ndef test_video_topic_drops_duration_modifier_after_about_clause():\n    from healthia_one.education_video_models import topic_from_text\n\n    assert topic_from_text("Create a one minute video about hypertension and blood pressure") == "hypertension and blood pressure"\n    assert "pressão" in topic_from_text("Crie um vídeo curto sobre hipertensão e pressão arterial por 1 minuto").lower()\n'''
    if "test_direct_spanish_video_request_extracts_clinical_topic_not_duration" not in text:
        text += addition
    path.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    patch_models()
    patch_planner()
    patch_tests()
